package com.nigson.commerce.fulfillment;
import java.net.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import com.sun.net.httpserver.HttpServer;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import static org.assertj.core.api.Assertions.*;
class HttpCarrierReconciliationTest {
 private final UUID shipment=UUID.randomUUID(),command=UUID.randomUUID(),correlation=UUID.randomUUID();
 private final CarrierReconciliationValues.Request input=new CarrierReconciliationValues.Request(UUID.randomUUID(),"MOCK","Synthetic operator reconciliation reason");
 @Test void sendsExactCompiledCommandAndReturnsActualJob()throws Exception{UUID job=UUID.randomUUID();var seen=new AtomicReference<String>();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{seen.set(e.getRequestURI().getPath());assertThat(e.getRequestHeaders().getFirst("Authorization")).isEqualTo("Bearer mock-workload");assertThat(e.getRequestHeaders().getFirst("X-Nigson-Actor")).isEqualTo("mock-actor");assertThat(e.getRequestHeaders().getFirst("Idempotency-Key")).isEqualTo(command.toString());assertThat(e.getRequestHeaders().getFirst("X-Correlation-ID")).isEqualTo(correlation.toString());assertThat(e.getRequestBody().readAllBytes()).isEqualTo(HttpCarrierReconciliation.body(input));byte[] bytes=EventCodec.JSON.writeValueAsBytes(new CarrierReconciliationValues.Result(shipment,"UNKNOWN",job));e.getResponseHeaders().set("Content-Type","application/json");e.sendResponseHeaders(202,bytes.length);try(var out=e.getResponseBody()){out.write(bytes);}});server.start();try{var client=new HttpCarrierReconciliation("test","http://127.0.0.1:"+server.getAddress().getPort(),r->{assertThat(r.api()).isEqualTo("API-196");return "mock-workload";});assertThat(client.reconcile(shipment,input,command,"mock-actor",correlation).jobId()).isEqualTo(job);assertThat(seen.get()).isEqualTo("/internal/v1/carrier/shipments/"+shipment+"/reconciliation");}finally{server.stop(0);}}
 @Test void foreignOversizedAndRedirectedResponsesRemainUncertainWithoutLeakingDiagnostics()throws Exception{var mode=new AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",e->{e.getRequestBody().readAllBytes();int selected=mode.get();byte[] body=selected==1?"a".repeat(65537).getBytes():EventCodec.JSON.writeValueAsBytes(selected==0?new CarrierReconciliationValues.Result(UUID.randomUUID(),"BOOKED",UUID.randomUUID()):Map.of("code","NOT_FOUND","detail","protected remote diagnostics"));e.getResponseHeaders().set("Content-Type",selected==3?"application/problem+json":"application/json");if(selected==2)e.getResponseHeaders().set("Location","https://untrusted.example.invalid/");e.sendResponseHeaders(selected==2?307:selected==3?404:202,body.length);try(var out=e.getResponseBody()){out.write(body);}});server.start();try{var client=new HttpCarrierReconciliation("test","http://127.0.0.1:"+server.getAddress().getPort(),r->"mock-workload");for(int i=0;i<4;i++){mode.set(i);assertThatThrownBy(()->client.reconcile(shipment,input,command,"mock-actor",correlation)).isInstanceOfSatisfying(Problem.Failure.class,f->assertThat(f.code).isEqualTo(ProblemCode.PROVIDER_OUTCOME_UNKNOWN)).hasMessageNotContaining("protected remote");}}finally{server.stop(0);}}
 @Test void productionTargetsAndTransactionGuardsFailBeforeCredentials(){assertThatThrownBy(()->new HttpCarrierReconciliation("prod","http://127.0.0.1:9",r->"mock-workload")).hasMessage("INTEGRATION_TARGET_REQUIRED");var client=new HttpCarrierReconciliation("test","http://127.0.0.1:9",r->{throw new AssertionError("NO_CREDENTIALS_UNDER_LOCK");});TransactionSynchronizationManager.setActualTransactionActive(true);try{assertThatThrownBy(()->client.reconcile(shipment,input,command,"mock-actor",correlation)).hasMessage("IDENTITY_HTTP_OUTSIDE_TRANSACTION_REQUIRED");}finally{TransactionSynchronizationManager.setActualTransactionActive(false);}}
 @Test void closedValuesRejectUnknownFieldsUntrustedStatesAndControlCharacters(){assertThatThrownBy(()->CarrierReconciliationValues.reason(EventCodec.JSON.valueToTree(Map.of("reason","Synthetic operator reason","mode","LIVE")))).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->new CarrierReconciliationValues.Request(UUID.randomUUID(),"MOCK","Synthetic reason\ncommand")).hasMessage("VALIDATION_ERROR");assertThatThrownBy(()->CarrierReconciliationValues.result(EventCodec.JSON.valueToTree(Map.of("shipmentId",shipment,"state","SUCCEEDED","jobId",UUID.randomUUID())),shipment)).hasMessage("VALIDATION_ERROR");}
}
